// Page-level rules: the JSON-LD must agree with the HTML around it, and the head must be sound.
// The HTML is generated by this repo, so small regular expressions are enough and keep the
// validator dependency-free. They are not a general HTML parser.

import { decode, stripTags, visibleText } from '../lib/html.mjs';

const TAG = (name, html) => html.match(new RegExp(`<${name}\\b[^>]*>([\\s\\S]*?)</${name}>`, 'i'));
const attr = (tag, name) => tag.match(new RegExp(`\\b${name}=("([^"]*)"|'([^']*)')`, 'i'))?.slice(2).find((v) => v !== undefined);

function metaContent(html, key, value) {
  for (const tag of html.matchAll(/<meta\b[^>]*>/gi)) {
    if (attr(tag[0], key) === value) return decode(attr(tag[0], 'content') ?? '');
  }
  return null;
}

const typesOf = (node) => [].concat(node['@type'] ?? []);
const isType = (node, ...names) => typesOf(node).some((t) => names.includes(t));

/**
 * @param {string} html built page
 * @param {{ nodes: object[], expectedUrl: string, siteUrl: string, indexable?: boolean, requireGraph?: boolean }} context
 */
export function checkPage(html, { nodes, expectedUrl, siteUrl, indexable = true, requireGraph = true }) {
  const issues = [];
  const add = (level, code, message) => issues.push({ level, code, message });

  const lang = html.match(/<html\b[^>]*\blang=["']([^"']+)["']/i)?.[1];
  if (!lang) add('error', 'HT001', '<html> has no lang attribute.');

  const title = TAG('title', html) ? decode(TAG('title', html)[1].trim()) : '';
  if (!title) add('error', 'HT002', 'Missing <title>.');
  else if (title.length < 10 || title.length > 75) add('warn', 'HT002', `Title is ${title.length} characters; aim for 10 to 75.`);

  const description = metaContent(html, 'name', 'description');
  if (!description) add('error', 'HT003', 'Missing meta description.');
  else if (description.length < 50 || description.length > 170) {
    add('warn', 'HT003', `Meta description is ${description.length} characters; aim for 50 to 170.`);
  }

  const canonical = html.match(/<link\b[^>]*rel=["']canonical["'][^>]*>/i);
  const canonicalHref = canonical ? decode(attr(canonical[0], 'href') ?? '') : '';
  if (!canonicalHref) add('error', 'HT004', 'Missing <link rel="canonical">.');
  else if (canonicalHref !== expectedUrl) add('error', 'HT004', `Canonical is ${canonicalHref}; expected ${expectedUrl}.`);

  const robots = metaContent(html, 'name', 'robots') ?? '';
  if (indexable && /noindex/i.test(robots)) add('error', 'HT005', 'Indexable page has a noindex robots directive.');
  if (!indexable && !/noindex/i.test(robots)) add('warn', 'HT005', 'Non-indexable page should carry noindex.');

  const h1s = [...html.matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)].map((m) => stripTags(m[1]));
  if (h1s.length !== 1) add('error', 'HT006', `Expected exactly one <h1>, found ${h1s.length}.`);

  if (!metaContent(html, 'name', 'viewport')) add('error', 'HT007', 'Missing viewport meta tag.');
  for (const key of ['og:title', 'og:description', 'og:url', 'og:image']) {
    if (!metaContent(html, 'property', key)) add('warn', 'HT008', `Missing ${key}.`);
  }
  for (const img of html.matchAll(/<img\b[^>]*>/gi)) {
    if (attr(img[0], 'alt') === undefined) add('error', 'HT009', `Image without alt text: ${attr(img[0], 'src')}.`);
  }

  if (!requireGraph) return issues;

  // Competing markup: microdata or RDFa describing the same page.
  if (/\bitemscope\b|\bitemtype=|\btypeof=|\bvocab=/i.test(html.replace(/<script[\s\S]*?<\/script>/gi, ''))) {
    add('error', 'LD040', 'Microdata or RDFa found alongside JSON-LD. Two competing descriptions of one page are worse than either alone.');
  }

  // Parity: the markup must describe what the page shows.
  const page = nodes.find((n) => isType(n, 'WebPage', 'ProfilePage', 'CollectionPage'));
  if (page) {
    if (page.url !== canonicalHref) add('error', 'LD050', `WebPage url ${page.url} does not match the canonical ${canonicalHref}.`);
    if (page.name !== title) add('error', 'LD051', `WebPage name ${JSON.stringify(page.name)} does not match the <title> ${JSON.stringify(title)}.`);
    if (description && page.description !== description) add('warn', 'LD052', 'WebPage description does not match the meta description.');
    if (page.inLanguage && lang && page.inLanguage !== lang) add('warn', 'LD058', `inLanguage ${page.inLanguage} does not match <html lang="${lang}">.`);
  }

  const text = visibleText(html);
  const times = [...html.matchAll(/<time\b[^>]*datetime=["']([^"']+)["']/gi)].map((m) => m[1]);
  const article = nodes.find((n) => isType(n, 'Article', 'BlogPosting', 'NewsArticle'));
  if (article) {
    if (h1s[0] !== article.headline) add('error', 'LD053', `Article headline ${JSON.stringify(article.headline)} does not match the visible <h1> ${JSON.stringify(h1s[0])}.`);
    for (const property of ['datePublished', 'dateModified']) {
      if (article[property] && !times.includes(article[property])) {
        add('error', 'LD054', `${property} ${article[property]} is not shown on the page in a <time datetime> element.`);
      }
    }
    const byId = new Map(nodes.map((n) => [n['@id'], n]));
    const authorRef = [].concat(article.author ?? [])[0];
    const author = authorRef?.['@id'] ? byId.get(authorRef['@id']) : authorRef;
    if (author?.name && !text.includes(author.name)) {
      add('error', 'LD055', `Author "${author.name}" is not visible on the page.`);
    }
  }

  const crumbs = nodes.find((n) => isType(n, 'BreadcrumbList'));
  if (crumbs) {
    const nav = html.match(/<nav\b[^>]*aria-label=["']Breadcrumb["'][^>]*>([\s\S]*?)<\/nav>/i);
    const visible = nav ? [...nav[1].matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)].map((m) => stripTags(m[1])) : [];
    const expected = [].concat(crumbs.itemListElement ?? []).map((item) => item.name);
    if (JSON.stringify(visible) !== JSON.stringify(expected)) {
      add('error', 'LD056', `Breadcrumb markup ${JSON.stringify(expected)} does not match the visible breadcrumb ${JSON.stringify(visible)}.`);
    }
  }

  return issues;
}
